={{
(() => {
  const raw = $json.property_data_de_reuni_o?.start;
  if (!raw) return "Sem data";

  const date = new Date(raw);

  const data = date.toLocaleDateString('pt-BR', {
    timeZone: 'America/Sao_Paulo'
  });

  const hora = date.toLocaleTimeString('pt-BR', {
    timeZone: 'America/Sao_Paulo',
    hour: '2-digit',
    minute: '2-digit'
  });

  return `Data: ${data} às ${hora}`;
})()
}}

={{
(() => {
  const rawDate = $json.property_data_de_reuni_o?.start;

  if (!rawDate) return false;

  const meetingDate = rawDate.split('T')[0]; // "2026-03-19"
  const today = new Date().toISOString().split('T')[0]; // "2026-03-20"

  return meetingDate < today;
})()
}}

=={{ (() => {
  const raw = $('Webhook').item.json.body.conversation?.messages?.[0]?.attachments?.[0]?.fallback_title || '';
  let digits = raw.replace(/\D/g, '');
  if (digits.startsWith('55') && (digits.length === 12 || digits.length === 13)) {
    digits = digits.slice(2);
  }
  if (digits.length === 10) {
    digits = digits.slice(0, 2) + '9' + digits.slice(2);
  }
  return digits ? '55' + digits : '';
})() }}

={{
(raw => {
  let t = (raw || "").toString().replace(/\s+/g, "").replace(/\D/g, "");
  t = t.replace(/^0+/, "");
  if (t.length === 8) {
    t = "11" + "9" + t;
  } else if (t.length === 9) {
    t = "11" + t;
  } else if (t.length === 10) {
    t = t.replace(/^(\d{2})(\d{8})$/, "$19$2");
  } else if (t.length === 11) {
    t = "55" + t;
  } else if (t.length === 12) {
    t = t.slice(0, 4) + "9" + t.slice(4);
  } else if (t.length > 13) {
    t = t.slice(-13);
  }
  return t;
})($('Webhook').item.json.body.conversation.meta.sender.phone_number)
}}

